import { useAuth } from "@/_core/hooks/useAuth";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { protectedBranchCoverage } from "../../../shared/protectedBranchCoverage";
import { toast } from "sonner";
import {
  Activity,
  AlertTriangle,
  BellRing,
  Blocks,
  Check,
  ChevronRight,
  CircleDot,
  ClipboardCheck,
  Clock3,
  CloudOff,
  Code2,
  GitBranch,
  Github,
  History,
  Laptop,
  LockKeyhole,
  Pause,
  Plus,
  RefreshCw,
  RotateCcw,
  ScanSearch,
  Send,
  Settings2,
  ShieldCheck,
  TimerReset,
  TriangleAlert,
  Workflow,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";

type Section = "overview" | "repositories" | "policies" | "extensions" | "activity" | "alerts";
type ExtensionItem = {
  extensionKey: string;
  name: string;
  category: "ide" | "git_host" | "notification" | "team_workflow";
  description: string;
  scopes: string[];
  icon: typeof Laptop;
  color: string;
};

const extensions: ExtensionItem[] = [
  { extensionKey: "vscode-companion", name: "VS Code companion", category: "ide", description: "Show local policy, queue, and recovery state without moving code off-device.", scopes: ["Read workspace metadata", "Open local review queue"], icon: Laptop, color: "#93beff" },
  { extensionKey: "github-visibility", name: "GitHub visibility", category: "git_host", description: "Link branch protection and pull-request context to the Studio decision ledger.", scopes: ["Read repository metadata", "Read branch protection"], icon: Github, color: "#d3b6ff" },
  { extensionKey: "incident-alerts", name: "Incident alerts", category: "notification", description: "Route only selected safety alerts to an approved notification surface.", scopes: ["Send opted-in notifications"], icon: BellRing, color: "#ffc17e" },
  { extensionKey: "team-handoff", name: "Team handoff", category: "team_workflow", description: "Prepare compact records when a reviewed action needs a human teammate.", scopes: ["Create handoff metadata", "Read policy label"], icon: Workflow, color: "#83dfbd" },
];

const defaultAlerts = { automationPaused: false, secretRiskBlocked: false, pushFailed: false, extensionNeedsAttention: false };

function getSection(path: string): Section {
  const section = path.split("/")[1] || "overview";
  return ["repositories", "policies", "extensions", "activity", "alerts"].includes(section) ? section as Section : "overview";
}

function formatTime(value?: Date | string | null) {
  if (!value) return "Not yet";
  return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value));
}

function parseList(value: string | undefined | null, fallback: string[]) {
  try { return value ? JSON.parse(value) : fallback; } catch { return fallback; }
}

function PanelHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: { label: string; onClick: () => void } }) {
  return <div className="flex items-start justify-between gap-3"><div><p className="font-mono text-[10px] uppercase tracking-[0.16em] text-[#75888e]">{eyebrow}</p><h2 className="mt-1.5 text-base font-bold tracking-[-0.04em] text-white">{title}</h2></div>{action && <button onClick={action.onClick} className="focus-ring rounded-lg px-2 py-1 text-xs font-semibold text-[#bdf26a] hover:bg-[#b7f05a]/10">{action.label}</button>}</div>;
}

function Field({ label, hint, children }: { label: string; hint: string; children: React.ReactNode }) {
  return <div className="space-y-2"><div><Label className="text-xs font-semibold text-[#d9e5df]">{label}</Label><p className="mt-0.5 text-[11px] text-[#788b90]">{hint}</p></div>{children}</div>;
}

export default function Home() {
  const { isAuthenticated } = useAuth();
  const [location, setLocation] = useLocation();
  const section = getSection(location);
  const utils = trpc.useUtils();
  const dashboard = trpc.studio.dashboard.useQuery(undefined, { enabled: isAuthenticated });
  const connectRepository = trpc.studio.connectRepository.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });
  const updatePolicy = trpc.studio.updatePolicy.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });
  const setExtension = trpc.studio.setExtension.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });
  const requestRecovery = trpc.studio.requestRecovery.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });
  const reviewAction = trpc.studio.reviewAction.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });
  const updateNotifications = trpc.studio.updateNotifications.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });
  const sendTestAlert = trpc.studio.sendTestAlert.useMutation({ onSuccess: () => utils.studio.dashboard.invalidate() });

  const [connectOpen, setConnectOpen] = useState(false);
  const [policyOpen, setPolicyOpen] = useState(false);
  const [recoveryOpen, setRecoveryOpen] = useState(false);
  const [extensionOpen, setExtensionOpen] = useState(false);
  const [activeExtension, setActiveExtension] = useState<ExtensionItem | null>(null);
  const [repositoryForm, setRepositoryForm] = useState({ name: "", origin: "", defaultBranch: "main" });
  const [alertSettings, setAlertSettings] = useState(defaultAlerts);

  const repositories = dashboard.data?.repositories ?? [];
  const policies = dashboard.data?.policies ?? [];
  const preferences = dashboard.data?.extensions ?? [];
  const activity = dashboard.data?.activity ?? [];
  const recoveries = dashboard.data?.recovery ?? [];
  const queuedActions = dashboard.data?.queuedActions ?? [];
  const repository = repositories[0];
  const policy = repository ? policies.find((item: any) => item.repositoryId === repository.id) : undefined;
  const defaults = useMemo(() => ({
    protectedBranches: parseList(policy?.protectedBranches, [repository?.defaultBranch || "main", "master"]),
    ignoreRules: parseList(policy?.ignoreRules, [".env", "*.pem", "node_modules/**"]),
    debounceSeconds: policy?.debounceSeconds ?? 20,
    commitApprovalMode: policy?.commitApprovalMode ?? "review",
    pushApprovalMode: policy?.pushApprovalMode ?? "review",
    secretRiskMode: policy?.secretRiskMode ?? "block",
  }), [policy, repository?.defaultBranch]);

  useEffect(() => {
    if (dashboard.data?.notifications) {
      const { automationPaused, secretRiskBlocked, pushFailed, extensionNeedsAttention } = dashboard.data.notifications;
      setAlertSettings({ automationPaused, secretRiskBlocked, pushFailed, extensionNeedsAttention });
    }
  }, [dashboard.data?.notifications]);

  const requireSignIn = () => {
    if (isAuthenticated) return false;
    toast.message("Sign in to persist this control", { description: "Policies, decisions, extensions, and alert consent are retained per user." });
    return true;
  };
  const go = (next: Section) => setLocation(next === "overview" ? "/" : `/${next}`);
  const saveRepository = () => {
    if (requireSignIn()) return;
    connectRepository.mutate(repositoryForm, { onSuccess: () => { toast.success("Repository connected in paused mode", { description: "Studio stored metadata only; no Git command was issued." }); setConnectOpen(false); setRepositoryForm({ name: "", origin: "", defaultBranch: "main" }); }, onError: error => toast.error("Repository could not be saved", { description: error.message }) });
  };
  const savePolicy = (form: typeof defaults) => {
    if (!repository || requireSignIn()) return;
    updatePolicy.mutate({ repositoryId: repository.id, ...form }, { onSuccess: () => { toast.success("Safety policy saved", { description: "A local companion must validate the policy before it operates." }); setPolicyOpen(false); }, onError: error => toast.error("Policy could not be saved", { description: error.message }) });
  };
  const saveExtension = (extension: ExtensionItem, enabled: boolean, configuration: Record<string, unknown> = {}) => {
    if (requireSignIn()) return;
    setExtension.mutate({ extensionKey: extension.extensionKey, name: extension.name, category: extension.category, description: extension.description, enabled, configuration, permissionScopes: extension.scopes }, { onSuccess: () => toast.success(`${extension.name} ${enabled ? "enabled" : "disabled"}`, { description: "Only its declared scopes are retained." }), onError: error => toast.error("Extension preference could not be saved", { description: error.message }) });
  };
  const decide = (actionId: number, decision: "approved" | "rejected") => {
    if (requireSignIn()) return;
    reviewAction.mutate({ actionId, decision }, { onSuccess: () => toast.success(decision === "approved" ? "Approval recorded" : "Queued action rejected", { description: "The companion must re-check policy before any Git operation proceeds." }), onError: error => toast.error("Action could not be reviewed", { description: error.message }) });
  };
  const recover = (type: "undo" | "revert") => {
    if (!repository || requireSignIn()) return;
    requestRecovery.mutate({ repositoryId: repository.id, type, targetRef: "HEAD" }, { onSuccess: () => { toast.success(`${type === "undo" ? "Undo" : "Revert"} request saved`, { description: "A local companion confirms the Git-native action." }); setRecoveryOpen(false); }, onError: error => toast.error("Recovery could not be requested", { description: error.message }) });
  };
  const saveAlerts = () => {
    if (requireSignIn()) return;
    updateNotifications.mutate(alertSettings, { onSuccess: () => toast.success("Alert preferences saved", { description: "Only categories you explicitly enabled can be delivered." }), onError: error => toast.error("Alert settings could not be saved", { description: error.message }) });
  };
  const testAlert = (category: keyof typeof defaultAlerts) => {
    if (requireSignIn()) return;
    sendTestAlert.mutate({ category }, { onSuccess: result => result.delivered ? toast.success("Opt-in test alert sent") : toast.message("Alert not sent", { description: "Enable and save this category before testing delivery." }), onError: error => toast.error("Alert test could not run", { description: error.message }) });
  };

  const header = <header className="mb-7 flex flex-col gap-5 border-b border-white/[0.08] pb-6 sm:flex-row sm:items-center sm:justify-between"><div><div className="mb-2 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.16em] text-[#82949a]"><span>Autopilot Studio</span><ChevronRight className="h-3 w-3" /><span className="text-[#c2d3c9]">{section === "overview" ? "Control room" : section}</span></div><h1 className="text-2xl font-extrabold tracking-[-0.055em] text-white sm:text-[30px]">{section === "overview" ? "Automation with receipts." : section[0].toUpperCase() + section.slice(1)}</h1></div><div className="flex flex-wrap items-center gap-2"><Badge variant="outline" className="gap-1.5 rounded-full border-[#b7f05a]/25 bg-[#b7f05a]/[0.07] px-3 py-1.5 font-mono text-[10px] uppercase tracking-[0.12em] text-[#c9f784]"><LockKeyhole className="h-3 w-3" />Local-first</Badge><Badge variant="outline" className="gap-1.5 rounded-full border-white/[0.12] bg-white/[0.025] px-3 py-1.5 font-mono text-[10px] uppercase tracking-[0.12em] text-[#a8b7b5]"><CloudOff className="h-3 w-3" />{isAuthenticated ? "Private workspace" : "Preview workspace"}</Badge><Button onClick={() => setConnectOpen(true)} className="h-9 rounded-xl bg-[#b7f05a] px-3.5 text-xs font-bold text-[#121a0c] hover:bg-[#c9f77d]"><Plus className="mr-1.5 h-3.5 w-3.5" />Connect repository</Button></div></header>;

  return <div className="mx-auto max-w-[1520px]">{header}
    {dashboard.isError && isAuthenticated ? <ErrorPanel onRetry={() => dashboard.refetch()} /> : dashboard.isLoading && isAuthenticated ? <LoadingPanel /> : <>
      {section === "overview" && <Overview repositories={repositories} policies={policies} repository={repository} defaults={defaults} activity={activity} queuedActions={queuedActions} recoveries={recoveries} extensionCount={preferences.filter((item: any) => item.enabled).length} attention={activity.filter((item: any) => item.status === "blocked" || item.status === "failed").length} onConnect={() => setConnectOpen(true)} onPolicy={() => setPolicyOpen(true)} onRecovery={() => setRecoveryOpen(true)} onReview={decide} go={go} />}
      {section === "repositories" && <RepositoriesPanel repositories={repositories} onConnect={() => setConnectOpen(true)} onPolicy={() => setPolicyOpen(true)} />}
      {section === "policies" && <PolicyPanel repository={repository} defaults={defaults} onSave={savePolicy} onConnect={() => setConnectOpen(true)} saving={updatePolicy.isPending} />}
      {section === "extensions" && <ExtensionsPanel preferences={preferences} onToggle={saveExtension} onConfigure={(item: ExtensionItem) => { if (!requireSignIn()) { setActiveExtension(item); setExtensionOpen(true); } }} saving={setExtension.isPending} />}
      {section === "activity" && <ActivityPanel activity={activity} queuedActions={queuedActions} recoveries={recoveries} onReview={decide} onRecovery={() => setRecoveryOpen(true)} />}
      {section === "alerts" && <AlertsPanel values={alertSettings} onChange={setAlertSettings} onSave={saveAlerts} onTest={testAlert} saving={updateNotifications.isPending} />}
    </>}
    <ConnectDialog open={connectOpen} setOpen={setConnectOpen} form={repositoryForm} setForm={setRepositoryForm} onSave={saveRepository} saving={connectRepository.isPending} />
    <PolicyDialog open={policyOpen} setOpen={setPolicyOpen} repository={repository} defaults={defaults} onSave={savePolicy} saving={updatePolicy.isPending} />
    <RecoveryDialog open={recoveryOpen} setOpen={setRecoveryOpen} repository={repository} onRecover={recover} saving={requestRecovery.isPending} />
    <ExtensionDialog open={extensionOpen} setOpen={setExtensionOpen} extension={activeExtension} preference={activeExtension ? preferences.find((item: any) => item.extensionKey === activeExtension.extensionKey) : undefined} onSave={saveExtension} saving={setExtension.isPending} />
  </div>;
}

function Overview({ repositories, policies, repository, defaults, activity, queuedActions, recoveries, extensionCount, attention, onConnect, onPolicy, onRecovery, onReview, go }: any) {
  const safetyScore = repositories.length ? Math.round(repositories.reduce((sum: number, item: any) => sum + item.safetyScore, 0) / repositories.length) : 100;
  const recentCommits = activity.filter((item: any) => item.type === "committed" || item.type === "pushed");
  return <div className="space-y-5">
    <section className="noise-overlay studio-grid rise-in overflow-hidden rounded-[26px] border border-white/[0.1] bg-[linear-gradient(118deg,#14221e_0%,#101820_52%,#10151e_100%)] p-6 sm:p-8"><div className="relative z-10 grid gap-8 lg:grid-cols-[1.2fr_0.8fr] lg:items-end"><div className="max-w-2xl"><div className="mb-5 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#b7f05a] shadow-[0_0_16px_#b7f05a]" /><span className="font-mono text-[10px] uppercase tracking-[0.17em] text-[#a2b9a3]">Safety-first control plane</span></div><h2 className="text-[32px] font-extrabold leading-[1.02] tracking-[-0.065em] text-white sm:text-[46px]">Quiet automation.<br /><span className="text-[#b7f05a]">Clear accountability.</span></h2><p className="mt-5 max-w-lg text-sm leading-6 text-[#aebfba]">Studio manages policy, review decisions, and visibility. The companion watches files and runs Git locally—only inside rules you approved.</p><div className="mt-7 flex flex-wrap gap-2"><Button onClick={onConnect} className="rounded-xl bg-[#b7f05a] text-xs font-bold text-[#121a0c] hover:bg-[#c8f87a]"><Plus className="mr-1.5 h-3.5 w-3.5" />Connect repository</Button><Button onClick={() => go("policies")} variant="outline" className="rounded-xl border-white/[0.13] bg-white/[0.035] text-xs text-white hover:bg-white/[0.08]"><ShieldCheck className="mr-1.5 h-3.5 w-3.5" />Review safeguards</Button></div></div><div className="rounded-2xl border border-white/[0.11] bg-[#0b1116]/70 p-4"><div className="mb-4 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-[0.15em] text-[#90a09f]">Local handoff</span><Badge className="rounded-full bg-[#b7f05a]/10 px-2 py-1 font-mono text-[9px] uppercase tracking-[0.1em] text-[#bff56d]">No code upload</Badge></div><div className="space-y-2 font-mono text-[11px] leading-5 text-[#abb7b1]"><p><span className="text-[#6f827a]">01</span> inspect policy snapshot</p><p><span className="text-[#6f827a]">02</span> run local secret check</p><p><span className="text-[#6f827a]">03</span> queue or confirm action</p><p><span className="text-[#6f827a]">04</span> record decision metadata</p></div></div></div></section>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Repository posture" value={`${repositories.length} connected`} detail={repositories.length ? `${repositories.filter((item: any) => item.monitoringStatus === "active").length} monitoring` : "Ready when you are"} icon={GitBranch} tone="lime" /><Metric label="Safety score" value={`${safetyScore}/100`} detail="Review-first baseline" icon={ShieldCheck} tone="blue" /><Metric label="Enabled extensions" value={`${extensionCount}`} detail="Capability-bound" icon={Blocks} tone="violet" /><Metric label="Needs attention" value={`${attention}`} detail={attention ? "Review ledger" : "No active incidents"} icon={TriangleAlert} tone="orange" /></section>
    <section className="grid gap-5 xl:grid-cols-2"><InsightPanel repositories={repositories} policies={policies} activity={activity} recoveries={recoveries} /><RecentCommitPanel records={recentCommits} onView={() => go("activity")} /></section>
    <section className="grid gap-5 xl:grid-cols-[1.16fr_0.84fr]"><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-6"><PanelHeading eyebrow="Automation posture" title={repository ? repository.name : "Set guardrails first"} action={repository ? { label: "Edit policy", onClick: onPolicy } : undefined} />{repository ? <RepositoryPosture repository={repository} defaults={defaults} /> : <EmptyStart onConnect={onConnect} />}</div><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-6"><PanelHeading eyebrow="Recovery" title="Git-native exits" action={repository ? { label: "Request recovery", onClick: onRecovery } : undefined} /><p className="mt-3 text-sm leading-6 text-[#9eafb1]">Studio never rewrites remote history. It records undo or revert intent, then a local companion confirms the Git command.</p><div className="mt-5 space-y-2"><RecoveryLine icon={RotateCcw} label="Undo a local Autopilot commit" status={recoveries.length ? "Request recorded" : "Available on connect"} /><RecoveryLine icon={TimerReset} label="Revert an approved remote commit" status="Requires local confirmation" /></div></div></section>
    <section className="grid gap-5 xl:grid-cols-[0.86fr_1.14fr]"><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-6"><ReviewQueue repository={repository} actions={queuedActions} onReview={onReview} onPolicy={onPolicy} /></div><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-6"><ReviewHistory actions={queuedActions} compact onView={() => go("activity")} /></div></section>
  </div>;
}

function Metric({ label, value, detail, icon: Icon, tone }: any) { const colors: any = { lime: "bg-[#b7f05a]/10 text-[#c7f879]", blue: "bg-[#8cc5ff]/10 text-[#9bcfff]", violet: "bg-[#c7a6ff]/10 text-[#cfb5ff]", orange: "bg-[#ffb56f]/10 text-[#ffc17e]" }; return <div className="rounded-2xl border border-white/[0.085] bg-[#101820]/72 p-4"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-[#819399]">{label}</p><p className="mt-3 text-xl font-extrabold tracking-[-0.05em] text-white">{value}</p></div><div className={`grid h-9 w-9 place-items-center rounded-xl ${colors[tone]}`}><Icon className="h-4 w-4" /></div></div><p className="mt-3 text-xs text-[#91a3a4]">{detail}</p></div>; }
function Insight({ value, label, tone }: any) { const colors: any = { lime: "text-[#c7f879]", orange: "text-[#ffc17e]", blue: "text-[#9bcfff]", violet: "text-[#cfb5ff]" }; return <div className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-3"><p className={`text-lg font-extrabold tracking-[-0.05em] ${colors[tone]}`}>{value}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[0.11em] text-[#778b91]">{label}</p></div>; }
function InsightPanel({ repositories, policies, activity, recoveries }: any) { const relevant = activity.filter((item: any) => ["committed", "pushed", "blocked"].includes(item.type)); const approved = activity.filter((item: any) => ["committed", "pushed"].includes(item.type)).length; const posture = protectedBranchCoverage(repositories, policies); return <div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-6"><PanelHeading eyebrow="Safety-oriented insights" title="Healthy automation is reviewable" />{activity.length || repositories.length ? <><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><Insight value={relevant.length ? `${Math.round((approved / relevant.length) * 100)}%` : "0%"} label="Approved flow" tone="lime" /><Insight value={activity.filter((item: any) => item.status === "blocked").length} label="Blocks recorded" tone="orange" /><Insight value={activity.filter((item: any) => item.type === "paused").length} label="Pause events" tone="blue" /><Insight value={recoveries.length} label="Recovery requests" tone="violet" /></div><div className="mt-4 rounded-xl border border-white/[0.07] bg-[#0b1116]/55 p-3"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-semibold text-white">Protected-branch posture</p><p className="mt-1 text-[11px] text-[#8a9da0]">Each default branch is evaluated against its own saved policy.</p></div><span className={`font-mono text-sm font-semibold ${posture.covered === posture.total ? "text-[#c7f879]" : "text-[#ffc17e]"}`}>{posture.covered}/{posture.total}</span></div><Progress value={posture.total ? (posture.covered / posture.total) * 100 : 0} className="mt-3 h-1.5 bg-white/[0.07] [&>div]:bg-[#b7f05a]" />{posture.uncoveredRepositoryIds.length > 0 && <p className="mt-2 text-[10px] text-[#ffc17e]">{posture.uncoveredRepositoryIds.length} repository{posture.uncoveredRepositoryIds.length === 1 ? "" : "ies"} need protected-branch coverage.</p>}</div></> : <p className="mt-5 text-sm leading-6 text-[#91a3a6]">When a companion records local decision metadata, Studio will show review rates, blocks, pause frequency, recovery use, and protected-branch coverage here.</p>}</div>; }
function RecentCommitPanel({ records, onView }: any) { return <div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-6"><PanelHeading eyebrow="Recent approved work" title="Commit and push receipts" action={{ label: "Open ledger", onClick: onView }} />{records.length ? <div className="mt-5 space-y-2">{records.slice(0, 3).map((item: any) => <ActivityRow key={item.id} item={item} />)}</div> : <div className="mt-5 rounded-xl border border-dashed border-white/[0.1] bg-[#0b1116]/40 p-4"><p className="text-sm font-semibold text-[#dbe7e1]">No approved commits recorded</p><p className="mt-1.5 text-xs leading-5 text-[#84989b]">Receipts appear after a companion submits action metadata and the required review is recorded.</p></div>}</div>; }
function EmptyStart({ onConnect }: any) { return <div className="mt-6 rounded-2xl border border-dashed border-white/[0.12] bg-[#0b1116]/50 p-5"><div className="mb-4 grid h-10 w-10 place-items-center rounded-xl bg-[#b7f05a]/10 text-[#b7f05a]"><ShieldCheck className="h-5 w-5" /></div><p className="font-semibold text-white">A safe default is already selected.</p><p className="mt-2 max-w-lg text-sm leading-6 text-[#8fa1a4]">New repositories enter paused mode. Commit review, push review, protected branches, and secret blocking become an explicit policy—not a surprise.</p><Button onClick={onConnect} size="sm" className="mt-5 rounded-xl bg-white/[0.09] text-xs text-white hover:bg-white/[0.14]">Connect a repository</Button></div>; }
function RepositoryPosture({ repository, defaults }: any) { const branchProtected = defaults.protectedBranches.includes(repository.defaultBranch); return <div className="mt-6"><div className="rounded-2xl bg-[#0b1116]/65 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#8cc5ff]/10 text-[#9bcfff]"><GitBranch className="h-4 w-4" /></div><div><p className="text-sm font-semibold text-white">{repository.origin}</p><p className="mt-0.5 font-mono text-[10px] text-[#82939a]">DEFAULT / {repository.defaultBranch}</p></div></div><StatusPill status={repository.monitoringStatus} /></div></div><div className="mt-5"><div className="mb-2 flex items-center justify-between"><span className="text-xs text-[#94a6a7]">Safety posture</span><span className="font-mono text-xs font-medium text-[#c9f784]">{repository.safetyScore}/100</span></div><Progress value={repository.safetyScore} className="h-2 bg-white/[0.06] [&>div]:bg-[#b7f05a]" /></div><div className="mt-5 grid grid-cols-3 gap-2"><MiniSignal icon={ShieldCheck} label="Default branch" value={branchProtected ? "Protected" : "Needs policy"} alert={!branchProtected} /><MiniSignal icon={ScanSearch} label="Secrets" value="Block" /><MiniSignal icon={Send} label="Push" value="Review" /></div></div>; }
function StatusPill({ status }: any) { const style = status === "active" ? "border-[#b7f05a]/30 bg-[#b7f05a]/10 text-[#c7f879]" : status === "needs_attention" ? "border-[#ffb56f]/30 bg-[#ffb56f]/10 text-[#ffc17e]" : "border-white/[0.12] bg-white/[0.04] text-[#a6b5b4]"; return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 font-mono text-[9px] uppercase tracking-[0.11em] ${style}`}><CircleDot className="h-2.5 w-2.5" />{status === "active" ? "Monitoring" : status === "needs_attention" ? "Needs attention" : "Paused"}</span>; }
function MiniSignal({ icon: Icon, label, value, alert }: any) { return <div className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-3"><Icon className={`h-3.5 w-3.5 ${alert ? "text-[#ffc17e]" : "text-[#8ca8b1]"}`} /><p className="mt-2 font-mono text-[9px] uppercase tracking-[0.12em] text-[#71848b]">{label}</p><p className={`mt-1 text-xs font-semibold ${alert ? "text-[#ffc17e]" : "text-[#dce8e2]"}`}>{value}</p></div>; }
function RecoveryLine({ icon: Icon, label, status }: any) { return <div className="flex items-center gap-3 rounded-xl border border-white/[0.07] bg-white/[0.02] p-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-white/[0.06] text-[#c8d7d3]"><Icon className="h-3.5 w-3.5" /></div><div className="min-w-0 flex-1"><p className="text-xs font-medium text-[#dce6e1]">{label}</p><p className="mt-0.5 text-[11px] text-[#829499]">{status}</p></div><ChevronRight className="h-4 w-4 text-[#52656c]" /></div>; }
function ReviewQueue({ repository, actions, onReview, onPolicy }: any) { const pending = actions.filter((item: any) => item.status === "pending"); return <><PanelHeading eyebrow="Review queue" title={pending.length ? `${pending.length} action${pending.length === 1 ? "" : "s"} awaiting review` : "Nothing is waiting"} action={{ label: "Policy", onClick: onPolicy }} />{pending.length ? <div className="mt-5 space-y-3">{pending.slice(0, 3).map((action: any) => <QueuedActionCard key={action.id} action={action} onReview={onReview} />)}</div> : <div className="mt-8 flex flex-col items-center text-center"><div className="grid h-14 w-14 place-items-center rounded-2xl border border-[#b7f05a]/15 bg-[#b7f05a]/[0.07] text-[#bdf26a]"><ClipboardCheck className="h-6 w-6" /></div><p className="mt-4 text-sm font-semibold text-white">{repository ? "Your queue is clear" : "Review before anything runs"}</p><p className="mt-2 max-w-xs text-xs leading-5 text-[#8da0a2]">{repository ? "A companion-submitted action appears here with branch, changed-file count, risk level, and real approve or reject controls." : "Connect a repository to see queued commits and pushes."}</p></div>}</>; }
function QueuedActionCard({ action, onReview }: any) { const risk = action.riskLevel === "high" ? "text-[#ffc17e] border-[#ffbb70]/25 bg-[#ffbb70]/[0.08]" : action.riskLevel === "medium" ? "text-[#9bcfff] border-[#8cc5ff]/25 bg-[#8cc5ff]/[0.08]" : "text-[#c7f879] border-[#b7f05a]/25 bg-[#b7f05a]/[0.08]"; return <div className="rounded-xl border border-white/[0.09] bg-[#0b1116]/55 p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-white">{action.kind === "commit" ? "Commit review" : "Push review"} · <span className="font-mono text-[#a9bbb6]">{action.branch}</span></p><p className="mt-1 text-[11px] leading-5 text-[#899da0]">{action.summary}</p></div><span className={`shrink-0 rounded-full border px-2 py-1 font-mono text-[9px] uppercase tracking-[0.1em] ${risk}`}>{action.riskLevel}</span></div><div className="mt-3 flex items-center justify-between gap-3"><span className="font-mono text-[9px] uppercase tracking-[0.11em] text-[#70858b]">{action.changedFiles} changed files</span><div className="flex gap-1.5"><Button onClick={() => onReview(action.id, "rejected")} variant="outline" size="sm" className="h-7 rounded-lg border-white/[0.11] bg-white/[0.02] px-2 text-[10px] text-[#c9d6d0] hover:bg-white/[0.08]">Reject</Button><Button onClick={() => onReview(action.id, "approved")} size="sm" className="h-7 rounded-lg bg-[#b7f05a] px-2 text-[10px] font-bold text-[#121a0c] hover:bg-[#c8f87a]">Approve</Button></div></div></div>; }
function ReviewHistory({ actions, compact, onView }: any) { const reviewed = actions.filter((item: any) => item.status !== "pending"); return <><PanelHeading eyebrow="Review history" title="Decisions with context" action={onView ? { label: "Full ledger", onClick: onView } : undefined} />{reviewed.length ? <div className="mt-5 space-y-2">{reviewed.slice(0, compact ? 3 : 10).map((item: any) => <div key={item.id} className="rounded-xl border border-white/[0.08] bg-[#0b1116]/45 p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-white">{item.kind === "commit" ? "Commit" : "Push"} · <span className="font-mono text-[#b5c6c1]">{item.branch}</span></p><p className="mt-1 text-[11px] text-[#8a9da0]">{item.summary}</p></div><span className={`rounded-full px-2 py-1 font-mono text-[9px] uppercase tracking-[0.1em] ${item.status === "approved" ? "bg-[#b7f05a]/10 text-[#c7f879]" : "bg-[#ffbb70]/10 text-[#ffc17e]"}`}>{item.status}</span></div><div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 font-mono text-[9px] uppercase tracking-[0.1em] text-[#70858b]"><span>Risk / {item.riskLevel}</span><span>Files / {item.changedFiles}</span><span>Reviewed / {formatTime(item.reviewedAt)}</span></div>{item.decisionNote && <p className="mt-2 border-t border-white/[0.06] pt-2 text-[11px] italic text-[#a2b2b0]">“{item.decisionNote}”</p>}</div>)}</div> : <div className="mt-5 rounded-xl border border-dashed border-white/[0.1] bg-[#0b1116]/40 p-4"><p className="text-sm font-semibold text-[#dbe7e1]">No reviewed actions yet</p><p className="mt-1 text-xs leading-5 text-[#84989b]">Approved and rejected queue decisions will retain their branch, risk, file count, timestamp, and review note here.</p></div>}</>; }
function ActivityRow({ item }: any) { const colors: Record<string, string> = { success: "bg-[#b7f05a]", warning: "bg-[#ffbf75]", blocked: "bg-[#ff7d6e]", failed: "bg-[#ff7d6e]", info: "bg-[#8cc5ff]" }; return <div className="flex gap-3 rounded-xl p-2.5 transition hover:bg-white/[0.035]"><span className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${colors[item.status] || colors.info}`} /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><p className="truncate text-xs font-semibold text-[#e5eeea]">{item.title}</p><span className="shrink-0 font-mono text-[10px] text-[#71868b]">{formatTime(item.occurredAt)}</span></div><p className="mt-1 line-clamp-1 text-[11px] text-[#8d9fa1]">{item.summary}</p></div></div>; }

function RepositoriesPanel({ repositories, onConnect, onPolicy }: any) { return <div className="space-y-5"><section className="rounded-[24px] border border-white/[0.09] bg-[#101820]/80 p-6 sm:p-7"><div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.16em] text-[#75888e]">Repository registry</p><h2 className="mt-2 text-2xl font-extrabold tracking-[-0.055em] text-white">Visible, not invasive.</h2><p className="mt-3 max-w-xl text-sm leading-6 text-[#9daeb0]">Store repository identity, branch posture, and automation metadata. Source files and local Git credentials stay on the device running the companion.</p></div><Button onClick={onConnect} className="rounded-xl bg-[#b7f05a] text-xs font-bold text-[#121a0c] hover:bg-[#c8f87a]"><Plus className="mr-1.5 h-3.5 w-3.5" />Connect repository</Button></div></section>{repositories.length ? <div className="space-y-3">{repositories.map((item: any) => <div key={item.id} className="flex flex-col gap-4 rounded-2xl border border-white/[0.09] bg-[#101820]/75 p-5 sm:flex-row sm:items-center"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[#8cc5ff]/10 text-[#9bcfff]"><GitBranch className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold tracking-[-0.035em] text-white">{item.name}</h3><StatusPill status={item.monitoringStatus} /></div><p className="mt-1 truncate text-xs text-[#8b9da0]">{item.origin}</p></div><div className="grid grid-cols-2 gap-4 sm:text-right"><div><p className="font-mono text-[9px] uppercase tracking-[0.12em] text-[#73868b]">Default</p><p className="mt-1 text-xs font-semibold text-[#dae5e0]">{item.defaultBranch}</p></div><div><p className="font-mono text-[9px] uppercase tracking-[0.12em] text-[#73868b]">Safety</p><p className="mt-1 text-xs font-semibold text-[#c7f879]">{item.safetyScore}/100</p></div></div><Button variant="outline" onClick={onPolicy} className="rounded-xl border-white/[0.12] bg-white/[0.03] text-xs text-white hover:bg-white/[0.08]"><Settings2 className="mr-1.5 h-3.5 w-3.5" />Policy</Button></div>)}</div> : <div className="rounded-[24px] border border-dashed border-white/[0.13] bg-[#101820]/50 p-10 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#b7f05a]/10 text-[#b7f05a]"><GitBranch className="h-6 w-6" /></div><h3 className="mt-5 text-lg font-bold tracking-[-0.04em] text-white">No repositories connected</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#8fa1a4]">Connect metadata for a local repository, then decide what the companion may queue, commit, or push.</p></div>}</div>; }
function PolicyPanel({ repository, defaults, onSave, onConnect, saving }: any) { const [form, setForm] = useState(defaults); useEffect(() => setForm(defaults), [defaults]); if (!repository) return <div className="rounded-[24px] border border-white/[0.09] bg-[#101820]/75 p-8"><EmptyStart onConnect={onConnect} /></div>; return <div className="grid gap-5 xl:grid-cols-[1fr_0.82fr]"><section className="rounded-[24px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-7"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#b7f05a]/10 text-[#b7f05a]"><ShieldCheck className="h-5 w-5" /></div><div><p className="font-mono text-[10px] uppercase tracking-[0.15em] text-[#779098]">Policy / {repository.name}</p><h2 className="mt-1 text-xl font-extrabold tracking-[-0.05em] text-white">Guardrails before speed.</h2><p className="mt-2 text-sm leading-6 text-[#9aadae]">Review is the default for commits and pushes. Automatic push is the exception, not the starting point.</p></div></div><PolicyForm form={form} setForm={setForm} onSave={() => onSave(form)} saving={saving} /></section><aside className="space-y-4"><PolicyNote icon={LockKeyhole} title="Primary branches stay protected" text="The companion rejects direct automation on the protected branch list." /><PolicyNote icon={ScanSearch} title="Secret risk gets the final say" text="Block is the recommended default. Review stays visible but never silently allows exposure." /><PolicyNote icon={Clock3} title="Debounce reduces noisy commits" text="Wait for work to settle before queuing an action; do not infer intent from every keystroke." /></aside></div>; }
function PolicyNote({ icon: Icon, title, text }: any) { return <div className="rounded-2xl border border-white/[0.08] bg-[#101820]/65 p-4"><Icon className="h-4 w-4 text-[#9bcfff]" /><p className="mt-3 text-sm font-semibold text-white">{title}</p><p className="mt-1.5 text-xs leading-5 text-[#879a9c]">{text}</p></div>; }
function PolicyForm({ form, setForm, onSave, saving }: any) { return <div className="mt-7 space-y-6"><div className="grid gap-4 sm:grid-cols-2"><Field label="Protected branches" hint="One branch per line"><Textarea value={form.protectedBranches.join("\n")} onChange={event => setForm({ ...form, protectedBranches: event.target.value.split("\n").map(value => value.trim()).filter(Boolean) })} className="min-h-28 resize-none border-white/[0.1] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field><Field label="Ignore rules" hint="Never stage these paths"><Textarea value={form.ignoreRules.join("\n")} onChange={event => setForm({ ...form, ignoreRules: event.target.value.split("\n").map(value => value.trim()).filter(Boolean) })} className="min-h-28 resize-none border-white/[0.1] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Settle time" hint="Seconds before an action is queued"><Input type="number" min="5" max="3600" value={form.debounceSeconds} onChange={event => setForm({ ...form, debounceSeconds: Number(event.target.value) })} className="border-white/[0.1] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field><Field label="Secret-risk handling" hint="Recommended: block"><Select value={form.secretRiskMode} onValueChange={value => setForm({ ...form, secretRiskMode: value })}><SelectTrigger className="border-white/[0.1] bg-[#0a1015] text-white"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="block">Block risky action</SelectItem><SelectItem value="review">Require review</SelectItem><SelectItem value="notify">Notify only</SelectItem></SelectContent></Select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Commit approval" hint="Human gate before commit"><Select value={form.commitApprovalMode} onValueChange={value => setForm({ ...form, commitApprovalMode: value })}><SelectTrigger className="border-white/[0.1] bg-[#0a1015] text-white"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="review">Review before commit</SelectItem><SelectItem value="manual">Manual only</SelectItem><SelectItem value="automatic">Automatic (not recommended)</SelectItem></SelectContent></Select></Field><Field label="Push approval" hint="Human gate before remote changes"><Select value={form.pushApprovalMode} onValueChange={value => setForm({ ...form, pushApprovalMode: value })}><SelectTrigger className="border-white/[0.1] bg-[#0a1015] text-white"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="review">Review before push</SelectItem><SelectItem value="manual">Manual only</SelectItem><SelectItem value="automatic">Automatic (not recommended)</SelectItem></SelectContent></Select></Field></div><div className="flex justify-end border-t border-white/[0.08] pt-5"><Button onClick={onSave} disabled={saving} className="rounded-xl bg-[#b7f05a] text-xs font-bold text-[#121a0c] hover:bg-[#c8f87a]">{saving ? <RefreshCw className="mr-1.5 h-3.5 w-3.5 animate-spin" /> : <Check className="mr-1.5 h-3.5 w-3.5" />}Save safety policy</Button></div></div>; }
function ExtensionsPanel({ preferences, onToggle, onConfigure, saving }: any) { return <div className="space-y-5"><section className="rounded-[24px] border border-white/[0.09] bg-[#101820]/80 p-6 sm:p-7"><p className="font-mono text-[10px] uppercase tracking-[0.16em] text-[#75888e]">Extensions hub</p><h2 className="mt-2 text-2xl font-extrabold tracking-[-0.055em] text-white">Capability-bound, not carte blanche.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#9daeb0]">Every integration declares what it can read or do. New extensions begin disabled, with configuration and current health visible in Studio.</p></section><div className="grid gap-4 md:grid-cols-2">{extensions.map(extension => { const preference = preferences.find((item: any) => item.extensionKey === extension.extensionKey); const Icon = extension.icon; return <div key={extension.extensionKey} className="rounded-[22px] border border-white/[0.09] bg-[#101820]/75 p-5"><div className="flex items-start justify-between gap-4"><div className="grid h-11 w-11 place-items-center rounded-xl" style={{ backgroundColor: `${extension.color}14`, color: extension.color }}><Icon className="h-5 w-5" /></div><Switch checked={Boolean(preference?.enabled)} disabled={saving} onCheckedChange={value => onToggle(extension, value)} /></div><div className="mt-5"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold tracking-[-0.04em] text-white">{extension.name}</h3><span className="rounded-full border border-white/[0.1] px-2 py-0.5 font-mono text-[9px] uppercase tracking-[0.1em] text-[#8fa1a3]">{extension.category.replace("_", " ")}</span></div><p className="mt-2 min-h-12 text-xs leading-5 text-[#90a2a4]">{extension.description}</p></div><div className="mt-5 border-t border-white/[0.08] pt-4"><p className="font-mono text-[9px] uppercase tracking-[0.13em] text-[#6f8389]">Declared scope</p><div className="mt-2 flex flex-wrap gap-1.5">{extension.scopes.map(scope => <span key={scope} className="rounded-md bg-white/[0.045] px-2 py-1 text-[10px] text-[#a6b6b4]">{scope}</span>)}</div></div><div className="mt-5 flex items-end justify-between"><div><p className={`text-xs font-semibold ${preference?.enabled ? "text-[#bdf26a]" : "text-[#84969a]"}`}>{preference?.enabled ? `Enabled · ${preference.healthStatus}` : "Disabled by default"}</p>{preference?.lastCheckedAt && <p className="mt-1 text-[10px] text-[#6f8389]">Health checked {formatTime(preference.lastCheckedAt)}</p>}</div><button onClick={() => onConfigure(extension)} className="focus-ring text-xs font-semibold text-[#b7f05a] hover:text-[#c9f784]">Configure</button></div></div>; })}</div></div>; }
function ActivityPanel({ activity, queuedActions, recoveries, onReview, onRecovery }: any) { return <div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><section className="rounded-[24px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-7"><PanelHeading eyebrow="Append-only metadata" title="The decision ledger" />{activity.length ? <div className="mt-6 space-y-1">{activity.map((item: any) => <ActivityRow key={item.id} item={item} />)}</div> : <div className="mt-8 rounded-2xl border border-dashed border-white/[0.12] bg-[#0b1116]/45 p-8 text-center"><History className="mx-auto h-7 w-7 text-[#73898f]" /><p className="mt-4 text-sm font-semibold text-white">No activity yet</p><p className="mx-auto mt-2 max-w-md text-xs leading-5 text-[#8da0a2]">A trusted companion will record why actions were queued, approved, blocked, paused, or recovered—without sending source contents.</p></div>}</section><aside className="space-y-4"><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/75 p-5"><ReviewQueue repository={{}} actions={queuedActions} onReview={onReview} onPolicy={() => {}} /></div><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/75 p-5"><ReviewHistory actions={queuedActions} /></div><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/75 p-5"><PanelHeading eyebrow="Recovery history" title="Always an exit path" action={{ label: "Request", onClick: onRecovery }} />{recoveries.length ? <div className="mt-5 space-y-2">{recoveries.map((item: any) => <div key={item.id} className="rounded-xl border border-white/[0.08] bg-white/[0.025] p-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-white">{item.type === "undo" ? "Undo" : "Revert"} · {item.targetRef}</p><span className="font-mono text-[9px] uppercase tracking-[0.1em] text-[#ffc17e]">{item.status}</span></div><p className="mt-1 text-[11px] text-[#7f9397]">Requested {formatTime(item.requestedAt)}</p></div>)}</div> : <p className="mt-4 text-sm leading-6 text-[#90a2a3]">No recovery requests are waiting. Studio routes Git-native requests to the companion for confirmation.</p>}</div><div className="rounded-[22px] border border-[#8cc5ff]/15 bg-[#8cc5ff]/[0.05] p-5"><Code2 className="h-4 w-4 text-[#9bcfff]" /><p className="mt-3 text-sm font-semibold text-white">Why no force push?</p><p className="mt-1.5 text-xs leading-5 text-[#9db1b3]">Force pushing can overwrite collaborators’ history. Studio uses explicit recovery paths instead.</p></div></aside></div>; }
function AlertsPanel({ values, onChange, onSave, onTest, saving }: any) { const rows: any[] = [{ key: "automationPaused", title: "Automation paused", text: "A companion pauses because policy or repository state needs attention.", icon: Pause }, { key: "secretRiskBlocked", title: "Secret-risk block", text: "A local check blocks a staged change before it becomes a commit.", icon: ScanSearch }, { key: "pushFailed", title: "Push failed", text: "A reviewed push could not reach its configured remote destination.", icon: Send }, { key: "extensionNeedsAttention", title: "Extension needs attention", text: "An enabled integration reports a health or configuration issue.", icon: Blocks }]; return <div className="grid gap-5 xl:grid-cols-[1.08fr_0.92fr]"><section className="rounded-[24px] border border-white/[0.09] bg-[#101820]/80 p-5 sm:p-7"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#ffbc7d]/10 text-[#ffc17e]"><BellRing className="h-5 w-5" /></div><div><p className="font-mono text-[10px] uppercase tracking-[0.15em] text-[#778b90]">Opt-in delivery</p><h2 className="mt-1 text-xl font-extrabold tracking-[-0.05em] text-white">Useful alerts, without noise.</h2><p className="mt-2 text-sm leading-6 text-[#9aadae]">All categories are off by default. A category can be delivered only after you enable and save it.</p></div></div><div className="mt-7 space-y-2">{rows.map(row => { const Icon = row.icon; return <div key={row.key} className="flex gap-3 rounded-2xl border border-white/[0.08] bg-[#0b1116]/55 p-4"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white/[0.05] text-[#b3c6c1]"><Icon className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-white">{row.title}</p><p className="mt-1 text-xs leading-5 text-[#85999d]">{row.text}</p><button onClick={() => onTest(row.key)} className="focus-ring mt-2 text-[11px] font-semibold text-[#b7f05a] hover:text-[#c9f784]">Send test only if enabled</button></div><Switch checked={values[row.key]} onCheckedChange={value => onChange({ ...values, [row.key]: value })} /></div>; })}</div><div className="mt-5 flex justify-end border-t border-white/[0.08] pt-5"><Button onClick={onSave} disabled={saving} className="rounded-xl bg-[#b7f05a] text-xs font-bold text-[#121a0c] hover:bg-[#c8f87a]">{saving ? <RefreshCw className="mr-1.5 h-3.5 w-3.5 animate-spin" /> : <BellRing className="mr-1.5 h-3.5 w-3.5" />}Save alert choices</Button></div></section><aside className="space-y-4"><div className="rounded-[22px] border border-[#b7f05a]/15 bg-[#b7f05a]/[0.055] p-5"><LockKeyhole className="h-4 w-4 text-[#bdf26a]" /><p className="mt-3 text-sm font-semibold text-white">Explicit consent is the control.</p><p className="mt-1.5 text-xs leading-5 text-[#9eb59e]">A test alert uses the same gate as a real alert. One category never enables another.</p></div><div className="rounded-[22px] border border-white/[0.09] bg-[#101820]/70 p-5"><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-[#76898e]">Delivery boundary</p><p className="mt-3 text-sm leading-6 text-[#9bacad]">Studio records alert history and attention in the dashboard. Future notification extensions require explicit configuration and declared scopes.</p></div></aside></div>; }

function ConnectDialog({ open, setOpen, form, setForm, onSave, saving }: any) { return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="border-white/[0.12] bg-[#101820] text-white sm:max-w-[510px]"><DialogHeader><DialogTitle className="text-xl font-extrabold tracking-[-0.05em]">Connect repository metadata</DialogTitle><DialogDescription className="leading-6 text-[#92a4a5]">Studio registers repository identity and starts in paused mode. It does not inspect source files, clone a repository, or run Git commands.</DialogDescription></DialogHeader><div className="grid gap-4 py-4"><Field label="Repository name" hint="A label for this workspace"><Input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} placeholder="e.g. storefront-web" className="border-white/[0.11] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field><Field label="Remote or local reference" hint="Metadata only; no credentials"><Input value={form.origin} onChange={event => setForm({ ...form, origin: event.target.value })} placeholder="github.com/you/project" className="border-white/[0.11] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field><Field label="Default branch" hint="Protected by default"><Input value={form.defaultBranch} onChange={event => setForm({ ...form, defaultBranch: event.target.value })} className="border-white/[0.11] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field></div><DialogFooter><Button variant="ghost" onClick={() => setOpen(false)} className="text-[#9aadae] hover:bg-white/[0.06] hover:text-white">Cancel</Button><Button onClick={onSave} disabled={saving || !form.name || !form.origin} className="rounded-xl bg-[#b7f05a] text-xs font-bold text-[#121a0c] hover:bg-[#c8f87a]">{saving && <RefreshCw className="mr-1.5 h-3.5 w-3.5 animate-spin" />}Connect in paused mode</Button></DialogFooter></DialogContent></Dialog>; }
function PolicyDialog({ open, setOpen, repository, defaults, onSave, saving }: any) { const [form, setForm] = useState(defaults); useEffect(() => setForm(defaults), [defaults, open]); return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[88vh] overflow-y-auto border-white/[0.12] bg-[#101820] text-white sm:max-w-[760px]"><DialogHeader><DialogTitle className="text-xl font-extrabold tracking-[-0.05em]">{repository ? `Policy · ${repository.name}` : "Safe policy baseline"}</DialogTitle><DialogDescription className="leading-6 text-[#92a4a5]">These rules are an explicit contract for the local companion. Review and push approvals remain on until you deliberately choose otherwise.</DialogDescription></DialogHeader>{repository ? <PolicyForm form={form} setForm={setForm} onSave={() => onSave(form)} saving={saving} /> : <p className="py-6 text-sm text-[#95a7a9]">Connect a repository before saving a persistent policy.</p>}</DialogContent></Dialog>; }
function RecoveryDialog({ open, setOpen, repository, onRecover, saving }: any) { return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="border-white/[0.12] bg-[#101820] text-white sm:max-w-[500px]"><DialogHeader><DialogTitle className="text-xl font-extrabold tracking-[-0.05em]">Recovery request</DialogTitle><DialogDescription className="leading-6 text-[#92a4a5]">Studio records your intent; a local companion confirms the Git-native action. Remote history is never force-pushed or rewritten.</DialogDescription></DialogHeader>{repository ? <div className="grid gap-3 py-4"><button onClick={() => onRecover("undo")} disabled={saving} className="focus-ring flex items-start gap-3 rounded-2xl border border-white/[0.1] bg-[#0b1116]/65 p-4 text-left hover:border-[#b7f05a]/35"><RotateCcw className="mt-0.5 h-4 w-4 text-[#bdf26a]" /><div><p className="text-sm font-semibold text-white">Undo the latest local Autopilot commit</p><p className="mt-1 text-xs leading-5 text-[#84979a]">Restore the latest local commit to the working directory for review.</p></div></button><button onClick={() => onRecover("revert")} disabled={saving} className="focus-ring flex items-start gap-3 rounded-2xl border border-white/[0.1] bg-[#0b1116]/65 p-4 text-left hover:border-[#8cc5ff]/35"><TimerReset className="mt-0.5 h-4 w-4 text-[#9bcfff]" /><div><p className="text-sm font-semibold text-white">Create a safe revert request</p><p className="mt-1 text-xs leading-5 text-[#84979a]">Prepare a normal Git revert and preserve shared history.</p></div></button></div> : <p className="py-6 text-sm text-[#95a7a9]">Connect a repository before requesting recovery.</p>}<DialogFooter><Button variant="ghost" onClick={() => setOpen(false)} className="text-[#9aadae] hover:bg-white/[0.06] hover:text-white">Close</Button></DialogFooter></DialogContent></Dialog>; }
function ExtensionDialog({ open, setOpen, extension, preference, onSave, saving }: any) { const [label, setLabel] = useState(""); const [visibility, setVisibility] = useState(true); useEffect(() => { const config = (() => { try { return preference?.configuration ? JSON.parse(preference.configuration) : {}; } catch { return {}; } })(); setLabel(config.connectionLabel || ""); setVisibility(config.eventVisibility ?? true); }, [open, preference?.configuration]); if (!extension) return null; return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="border-white/[0.12] bg-[#101820] text-white sm:max-w-[520px]"><DialogHeader><DialogTitle className="text-xl font-extrabold tracking-[-0.05em]">Configure {extension.name}</DialogTitle><DialogDescription className="leading-6 text-[#92a4a5]">Settings are saved with this extension only. A local or provider-side integration still needs explicit consent before it uses a declared capability.</DialogDescription></DialogHeader><div className="grid gap-5 py-4"><Field label="Connection label" hint="A private name for this integration"><Input value={label} onChange={event => setLabel(event.target.value)} placeholder="e.g. My developer workspace" className="border-white/[0.11] bg-[#0a1015] text-white focus-visible:ring-[#b7f05a]" /></Field><div className="flex items-center justify-between rounded-xl border border-white/[0.08] bg-[#0b1116]/60 p-3.5"><div><p className="text-sm font-semibold text-white">Show decision metadata</p><p className="mt-1 text-xs text-[#84979a]">Allow the extension to display permitted action, policy, and health events.</p></div><Switch checked={visibility} onCheckedChange={setVisibility} /></div><div><p className="font-mono text-[9px] uppercase tracking-[0.13em] text-[#758a90]">Declared scope</p><div className="mt-2 flex flex-wrap gap-1.5">{extension.scopes.map((scope: string) => <span key={scope} className="rounded-md bg-white/[0.045] px-2 py-1 text-[10px] text-[#a6b6b4]">{scope}</span>)}</div></div></div><DialogFooter><Button variant="ghost" onClick={() => setOpen(false)} className="text-[#9aadae] hover:bg-white/[0.06] hover:text-white">Cancel</Button><Button onClick={() => onSave(extension, Boolean(preference?.enabled), { connectionLabel: label, eventVisibility: visibility })} disabled={saving} className="rounded-xl bg-[#b7f05a] text-xs font-bold text-[#121a0c] hover:bg-[#c8f87a]">{saving && <RefreshCw className="mr-1.5 h-3.5 w-3.5 animate-spin" />}Save extension settings</Button></DialogFooter></DialogContent></Dialog>; }
function ErrorPanel({ onRetry }: any) { return <div className="rounded-[26px] border border-[#ff7d6e]/25 bg-[#ff7d6e]/[0.055] p-8 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#ff7d6e]/10 text-[#ff9a8c]"><AlertTriangle className="h-6 w-6" /></div><h2 className="mt-5 text-xl font-extrabold tracking-[-0.045em] text-white">Studio could not load your workspace</h2><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#d2aaa3]">No automation action ran. Retry the visibility dashboard when your connection is ready; your local repository remains untouched.</p><Button onClick={onRetry} className="mt-5 rounded-xl bg-white/[0.1] text-xs text-white hover:bg-white/[0.16]"><RefreshCw className="mr-1.5 h-3.5 w-3.5" />Retry dashboard</Button></div>; }
function LoadingPanel() { return <div className="space-y-5"><div className="h-72 animate-pulse rounded-[26px] border border-white/[0.07] bg-white/[0.035]" /><div className="grid gap-3 sm:grid-cols-4">{Array.from({ length: 4 }).map((_, index) => <div key={index} className="h-28 animate-pulse rounded-2xl border border-white/[0.07] bg-white/[0.035]" />)}</div></div>; }
